import os
import json
import requests
from typing import Any, Dict, Optional


OPENAI_API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4.1-mini"


def extract_structured_json(text: str, schema: Optional[Dict[str, Any]] = None, model: str = DEFAULT_MODEL) -> Dict[str, Any]:
    """
    Calls a hosted LLM to extract structured JSON from free-form text.

    Args:
        text: Input text to extract structured data from.
        schema: Optional JSON schema describing the desired output.
        model: Concrete OpenAI model identifier.

    Returns:
        Parsed JSON object as a Python dict.
    """
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise EnvironmentError("OPENAI_API_KEY is required")

    if schema is None:
        schema = {
            "type": "object",
            "properties": {
                "people": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "name": {"type": "string"},
                            "role": {"type": "string"},
                            "email": {"type": "string"}
                        },
                        "required": ["name"],
                        "additionalProperties": True
                    }
                },
                "summary": {"type": "string"}
            },
            "required": ["people", "summary"],
            "additionalProperties": True
        }

    payload = {
        "model": model,
        "input": [
            {
                "role": "system",
                "content": "Extract structured JSON from the user's text. Return only valid JSON matching the requested schema."
            },
            {
                "role": "user",
                "content": text
            }
        ],
        "text": {
            "format": {
                "type": "json_schema",
                "name": "extracted_data",
                "schema": schema,
                "strict": True
            }
        }
    }

    response = requests.post(
        OPENAI_API_URL,
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        json=payload,
        timeout=60,
    )
    response.raise_for_status()
    data = response.json()

    extracted_text = None
    if "output" in data:
        for item in data["output"]:
            if item.get("type") == "message":
                for content in item.get("content", []):
                    if content.get("type") in ("output_text", "text"):
                        extracted_text = content.get("text", "")
                        if extracted_text:
                            break
            if extracted_text:
                break

    if not extracted_text:
        extracted_text = data.get("output_text") or data.get("text")

    if not extracted_text:
        raise ValueError("No JSON text found in model response")

    try:
        return json.loads(extracted_text)
    except json.JSONDecodeError as e:
        raise ValueError(f"Model returned invalid JSON: {e}\nRaw output: {extracted_text}") from e
